CREATE TABLE "benchmark_scores" (
    "id" text NOT NULL,
    "create_time" timestamptz NOT NULL,
    "benchmark_id" text NOT NULL,
    "model_id" text NOT NULL,
    "weights_sha" text DEFAULT ''::text NOT NULL,
    "status" int4 NOT NULL,
    "error" text DEFAULT ''::text NOT NULL,
    "report" jsonb DEFAULT '{}'::jsonb NOT NULL,
    "headline" float8 DEFAULT 0 NOT NULL,
    "scored_at" timestamptz,
    PRIMARY KEY ("id"),
    CONSTRAINT "uq_benchmark_scores_benchmark_id_model_id" UNIQUE ("benchmark_id", "model_id"),
    CONSTRAINT "ck_benchmark_scores_status_between_1_and_5" CHECK ((status >= 1) AND (status <= 5))
);
CREATE INDEX "ix_benchmark_scores_model_id" ON "benchmark_scores" ("model_id");
CREATE TABLE "benchmarks" (
    "id" text NOT NULL,
    "create_time" timestamptz NOT NULL,
    "name" text NOT NULL,
    "team_id" text,
    "description" text DEFAULT ''::text NOT NULL,
    "dataset_id" text NOT NULL,
    "target" text NOT NULL,
    "kind" text NOT NULL,
    "rows" int8 NOT NULL,
    "created_by" text DEFAULT ''::text NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "ck_benchmarks_kind_in_class_number_ranked" CHECK (kind = ANY (ARRAY['class'::text, 'number'::text, 'ranked'::text])),
    CONSTRAINT "ck_benchmarks_length_name_between_1_and_100" CHECK ((length(name) >= 1) AND (length(name) <= 100)),
    CONSTRAINT "ck_benchmarks_rows_1" CHECK (rows >= 1)
);
CREATE INDEX "ix_benchmarks_dataset_id" ON "benchmarks" ("dataset_id");
CREATE INDEX "ix_benchmarks_team_id_create_time_id" ON "benchmarks" ("team_id", "create_time" DESC, "id" DESC);
ALTER TABLE "benchmark_scores" ADD CONSTRAINT "fk_benchmark_scores_benchmark_id" FOREIGN KEY ("benchmark_id") REFERENCES "benchmarks" ("id") ON DELETE CASCADE;
